//! Runs the game's Domino mission scripts.
//!
//! Far Cry 3's missions, side activities and much of its scripted behaviour
//! are "Domino" graphs: Lua generated by Ubisoft's visual scripting tool, one
//! file per graph or box (`domino\user\fc3\...` for the game's own content,
//! `domino\system\...` for the boxes that reach into the engine). They run
//! here on an embedded Lua 5.1, with the runtime they expect around them
//! (`prelude.lua`) and the engine functions they call provided by the host
//! through [`Domino::register`]. Calls to functions the host hasn't provided
//! are logged (see [`Domino::take_unknown_calls`]) and return nothing.
//!
//! Values cross as the engine passes them: entity ids are decimal strings of
//! the 64-bit id (a Lua number can't hold one), [`INVALID_ID`] being none;
//! vectors are `{x, y, z}` arrays; callbacks name a box and one of its
//! methods.

use std::cell::RefCell;
use std::rc::Rc;

use mlua::{IntoLuaMulti, Lua, MultiValue, Table, Value};

/// Where the scripts come from (the converted cache, or the game's archives).
pub trait ScriptSource {
    /// A script by the path a graph names it with (`Domino/System/Door.lua`).
    fn script(&self, path: &str) -> Option<String>;
}

/// The control outputs a box's reflection header declares
/// (`-- <ControlOut Name="Acknowledged"/>`), but not the dynamic ones (a
/// table of numbered outputs the graph fills in).
pub fn control_outs(text: &str) -> Vec<String> {
    let mut outs = Vec::new();
    for line in text.lines() {
        let line = line.trim_start();
        if !line.starts_with("--") {
            if !line.is_empty() {
                break;
            }
            continue;
        }
        let Some(at) = line.find("<ControlOut") else { continue };
        let tag = &line[at..];
        if tag.to_ascii_lowercase().contains("dynamic=\"true\"") {
            continue;
        }
        let Some(name) = tag.split("Name=\"").nth(1).and_then(|r| r.split('"').next()) else { continue };
        if !name.is_empty() && !outs.iter().any(|o| o == name) {
            outs.push(name.to_string());
        }
    }
    outs
}

/// A graph's stateless uses of a box (`l0 = Boxes[GetPathID("...")];`, its
/// `_graph` set, its outputs plugged) with the outputs the box declares that
/// the use leaves unplugged plugged to `DummyFunction`, as the use's own
/// (none when nothing needs it). The class is shared: an output a graph
/// compiled before the box grew it never plugs kept whatever the last user
/// plugged, which then ran with this graph as its `_graph`
/// (base_c4_amanakitown_main's MissionGetState, Acknowledged, after a side
/// quest's `SideQuestAcknowledge`). Plugging and calling may be apart (a
/// graph's `en_<n>` plugs, a later `l0:In()` calls), so only the plugging
/// block is touched.
pub fn plug_stateless(text: &str, mut declared: impl FnMut(&str) -> Vec<String>) -> Option<String> {
    struct Block {
        var: String,
        path: String,
        graph_line: Option<usize>,
        assigned: Vec<String>,
    }
    let lines: Vec<&str> = text.lines().collect();
    let mut inserts: Vec<(usize, String)> = Vec::new();
    let mut open: Option<Block> = None;
    let mut close = |b: Block, inserts: &mut Vec<(usize, String)>| {
        let Some(at) = b.graph_line else { return };
        let missing: Vec<String> = declared(&b.path).into_iter().filter(|o| !b.assigned.iter().any(|a| a == o)).collect();
        if !missing.is_empty() {
            let indent: String = lines[at].chars().take_while(|c| c.is_whitespace()).collect();
            let add = missing.iter().map(|o| format!("{indent}{}.{o} = DummyFunction;", b.var)).collect::<Vec<_>>().join("\n");
            inserts.push((at, add));
        }
    };
    for (i, raw) in lines.iter().enumerate() {
        let line = raw.trim();
        if let Some(b) = open.as_mut() {
            let field = line.strip_prefix(b.var.as_str()).and_then(|r| r.strip_prefix('.'));
            if let Some(rest) = field {
                let name: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
                if name == "_graph" && rest[name.len()..].trim_start().starts_with('=') {
                    b.graph_line = Some(i);
                } else if !name.is_empty() {
                    b.assigned.push(name);
                }
                continue;
            }
            if let Some(b) = open.take() {
                close(b, &mut inserts);
            }
        }
        // `l0 = Boxes[GetPathID("Domino/System/X.lua")];`
        if let Some((var, rest)) = line.split_once(" = Boxes[GetPathID(\"") {
            if let Some(path) = rest.strip_suffix("\")];") {
                if var.starts_with('l') && var[1..].chars().all(|c| c.is_ascii_digit()) {
                    open = Some(Block { var: var.to_string(), path: path.to_string(), graph_line: None, assigned: Vec::new() });
                }
            }
        }
    }
    if let Some(b) = open.take() {
        close(b, &mut inserts);
    }
    if inserts.is_empty() {
        return None;
    }
    let mut out = String::with_capacity(text.len() + inserts.len() * 40);
    let mut next = inserts.iter().peekable();
    for (i, line) in lines.iter().enumerate() {
        out.push_str(line);
        out.push('\n');
        while let Some((_, add)) = next.next_if(|(at, _)| *at == i) {
            out.push_str(add);
            out.push('\n');
        }
    }
    Some(out)
}

/// The entity id that stands for none.
pub const INVALID_ID: &str = "18446744073709551615";

/// What `GetPathID` gives for a path: the archive's hash of it (CRC-64 of the
/// path in lower case with backslashes), as a decimal string.
pub fn path_id(path: &str) -> String {
    fc3_formats::hash::path_hash(&path.replace('/', "\\")).to_string()
}

#[derive(Default)]
struct State {
    /// Unknown natives called, with their arguments.
    unknown: Vec<String>,
    /// Resources graphs asked to load (path, kind).
    resources: Vec<(String, String)>,
    /// The runtime's own log lines (warnings, traces) and missing scripts.
    log: Vec<String>,
}

/// A Lua state running Domino graphs.
pub struct Domino {
    lua: Lua,
    state: Rc<RefCell<State>>,
}

/// A short rendering of a Lua value for logs.
pub fn describe(v: &Value) -> String {
    match v {
        Value::Nil => "nil".into(),
        Value::Boolean(b) => b.to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => format!("{:?}", s.to_string_lossy()),
        Value::Table(_) => "{..}".into(),
        Value::Function(_) => "fn".into(),
        other => other.type_name().into(),
    }
}

fn describe_all(args: MultiValue) -> Vec<String> {
    args.into_iter()
        .map(|v| match v {
            Value::String(s) => s.to_string_lossy(),
            other => describe(&other),
        })
        .collect()
}

impl Domino {
    pub fn new(source: impl ScriptSource + 'static) -> mlua::Result<Domino> {
        // The engine's VM has every standard library, `debug` included (the
        // scripts read call stacks); these are the game's own scripts.
        let lua = unsafe { Lua::unsafe_new_with(mlua::StdLib::ALL_SAFE | mlua::StdLib::DEBUG, mlua::LuaOptions::default()) };
        let state = Rc::new(RefCell::new(State::default()));
        let g = lua.globals();
        g.set("GetPathID", lua.create_function(|_, path: String| Ok(path_id(&path)))?)?;
        let source = Rc::new(source);
        let s = state.clone();
        let outs_by_path: RefCell<std::collections::HashMap<String, Vec<String>>> = RefCell::default();
        g.set(
            "__domino_load",
            lua.create_function(move |lua, path: String| match source.script(&path) {
                Some(text) => {
                    let outs = lua.create_sequence_from(control_outs(&text))?;
                    let declared = |box_path: &str| {
                        outs_by_path
                            .borrow_mut()
                            .entry(box_path.to_ascii_lowercase())
                            .or_insert_with(|| source.script(box_path).map(|t| control_outs(&t)).unwrap_or_default())
                            .clone()
                    };
                    let text = plug_stateless(&text, declared).unwrap_or(text);
                    lua.load(text).set_name(path).exec().map(|()| (true, Some(outs)))
                }
                None => {
                    s.borrow_mut().log.push(format!("missing script {path}"));
                    Ok((false, None))
                }
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_resource",
            lua.create_function(move |_, (path, kind): (String, Option<String>)| {
                s.borrow_mut().resources.push((path, kind.unwrap_or_default()));
                Ok(())
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_log",
            lua.create_function(move |_, args: MultiValue| {
                let parts = describe_all(args);
                s.borrow_mut().log.push(parts.join(" "));
                Ok(())
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_unknown",
            lua.create_function(move |_, args: MultiValue| {
                let mut parts = describe_all(args).into_iter();
                let name = parts.next().unwrap_or_default();
                let rest: Vec<String> = parts.collect();
                s.borrow_mut().unknown.push(format!("{name}({})", rest.join(", ")));
                Ok(())
            })?,
        )?;
        lua.load(include_str!("prelude.lua")).set_name("prelude").exec()?;
        Ok(Domino { lua, state })
    }

    pub fn lua(&self) -> &Lua {
        &self.lua
    }

    /// Provides a native function the scripts call.
    pub fn register<F, A, R>(&self, name: &str, f: F) -> mlua::Result<()>
    where
        F: Fn(&Lua, A) -> mlua::Result<R> + 'static,
        A: mlua::FromLuaMulti,
        R: mlua::IntoLuaMulti,
    {
        self.lua.globals().raw_set(name, self.lua.create_function(f)?)
    }

    /// Creates an instance of a graph or box with no entity behind it.
    pub fn create(&self, path: &str) -> mlua::Result<Table> {
        self.create_on(path, None, None, None)
    }

    /// Creates the instance of a graph a Domino component runs on an entity
    /// (and the prefab that entity belongs to), its inputs written before
    /// its `Init`, as the engine does.
    pub fn create_on(&self, path: &str, parent: Option<&str>, prefab: Option<&str>, inputs: Option<Table>) -> mlua::Result<Table> {
        let create: mlua::Function = self.lua.globals().get("__domino_create")?;
        create.call((path, parent, prefab, inputs))
    }

    /// Calls a box's method as the engine does (looked up on its class), with
    /// arguments; nothing happens if the class has no such method.
    pub fn call_with(&self, box_: &Table, method: &str, args: impl IntoLuaMulti) -> mlua::Result<MultiValue> {
        let call: mlua::Function = self.lua.globals().get("__domino_call")?;
        let mut all = vec![Value::Table(box_.clone()), Value::String(self.lua.create_string(method)?)];
        all.extend(args.into_lua_multi(&self.lua)?);
        call.call(MultiValue::from_iter(all))
    }

    /// Calls one of a box's inputs (`In`, `Start`, ...).
    pub fn call(&self, box_: &Table, input: &str) -> mlua::Result<()> {
        self.call_with(box_, input, ()).map(|_| ())
    }

    /// Logs every call into a script whose path contains `pattern` (its
    /// method name and line), for following a graph's flow; an empty pattern
    /// stops tracing.
    pub fn trace_calls(&self, pattern: &str) -> mlua::Result<()> {
        if pattern.is_empty() {
            return self.lua.load("debug.sethook()").exec();
        }
        self.lua
            .load(
                r#"
                local pattern = string.lower(...)
                debug.sethook(function()
                    local info = debug.getinfo(2, "Sn")
                    if info ~= nil and info.source ~= nil and string.find(string.lower(info.source), pattern, 1, true) then
                        __domino_log("call", info.source, info.name or "?", info.linedefined)
                    end
                end, "c")
                "#,
            )
            .call::<()>(pattern)
    }

    /// The unknown natives called since the last time, with their arguments.
    pub fn take_unknown_calls(&self) -> Vec<String> {
        std::mem::take(&mut self.state.borrow_mut().unknown)
    }

    /// The resources graphs asked to load since the last time (path, kind).
    pub fn take_resources(&self) -> Vec<(String, String)> {
        std::mem::take(&mut self.state.borrow_mut().resources)
    }

    /// The runtime's log lines since the last time (script warnings and
    /// traces, missing scripts).
    pub fn take_log(&self) -> Vec<String> {
        std::mem::take(&mut self.state.borrow_mut().log)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    struct Scripts(HashMap<String, String>);

    impl ScriptSource for Scripts {
        fn script(&self, path: &str) -> Option<String> {
            self.0.get(&path.to_ascii_lowercase()).cloned()
        }
    }

    /// Made-up scripts in the generated ones' shape: a stateful box, a
    /// stateless one, and a graph using both.
    fn scripts() -> Scripts {
        let mut m = HashMap::new();
        m.insert(
            "test/box.lua".into(),
            r#"
            Box = {};
            function Box:Init(cbox) self.count = 0; self.owner = cbox:GetParentEntity() end
            function Box:Fire() self.count = self.count + 1; NativeThing(self.Value); return self:Out() end
            export = Box; Box = nil;
            "#
            .into(),
        );
        m.insert(
            "test/stateless.lua".into(),
            r#"
            S = {};
            function S:Go() NativeThing(self.Value); return self:Out() end
            export = S; S = nil;
            "#
            .into(),
        );
        m.insert(
            "test/graph.lua".into(),
            r#"
            export = {};
            function export:LuaDependencies() return { [1] = "Test/Later.lua" } end;
            function export:Create(cbox)
                if (cbox:ShouldLoadResources() == true) then
                    cbox:RegisterBox("Test/Box.lua");
                    cbox:RegisterBox("Test/Stateless.lua");
                    cbox:RegisterBox("Test/Missing.lua");
                    cbox:LoadResource([[sndres0x00000001]], "CSoundResource");
                end;
            end;
            function export:Init(cbox)
                self.startedWith = self.Target;
                self[1] = cbox:CreateBox("Test/Box.lua");
                self[1]._graph = self;
                self[1].Out = self.f_1_Out;
            end;
            function export:In()
                local l0 = self[1];
                l0.Value = "42";
                l0:Fire();
            end;
            function export:f_1_Out()
                self = self._graph;
                self.done = true;
                local l0 = Boxes[GetPathID("Test/Stateless.lua")];
                l0._graph = self;
                l0.Value = self.startedWith;
                l0.Out = DummyFunction;
                l0:Go();
            end;
            "#
            .into(),
        );
        m.insert("test/later.lua".into(), "export = { loaded = true };".into());
        Scripts(m)
    }

    #[test]
    fn graphs_wire_and_run_their_boxes() {
        let d = Domino::new(scripts()).unwrap();
        let got = Rc::new(RefCell::new(Vec::new()));
        let g = got.clone();
        d.register("NativeThing", move |_, v: Option<String>| {
            g.borrow_mut().push(v);
            Ok(())
        })
        .unwrap();
        let inputs = d.lua().create_table().unwrap();
        inputs.set("Target", "7").unwrap();
        let graph = d.create_on("Test/Graph.lua", Some("123"), None, Some(inputs)).unwrap();
        d.call(&graph, "In").unwrap();
        assert!(graph.get::<bool>("done").unwrap());
        // The graph's own instance, then the stateless class with the input
        // the graph was given before its Init.
        assert_eq!(*got.borrow(), vec![Some("42".to_string()), Some("7".to_string())]);
        let child: Table = graph.get(1).unwrap();
        assert_eq!(child.get::<String>("owner").unwrap(), "123");
        assert_eq!(d.take_resources(), vec![("sndres0x00000001".to_string(), "CSoundResource".to_string())]);
        // A missing dependency is logged, not fatal; data dependencies load.
        assert_eq!(d.take_log(), vec!["missing script Test/Missing.lua".to_string()]);
        let later: Table = d.lua().load(r#"return Boxes[GetPathID("Test/Later.lua")]"#).eval().unwrap();
        assert!(later.get::<bool>("loaded").unwrap());
    }

    #[test]
    fn unknown_natives_are_logged() {
        let d = Domino::new(scripts()).unwrap();
        let graph = d.create("Test/Graph.lua").unwrap();
        d.call(&graph, "In").unwrap();
        let calls = d.take_unknown_calls();
        assert_eq!(calls[0], "NativeThing(42)");
    }

    #[test]
    fn engine_calls_skip_missing_methods() {
        let d = Domino::new(scripts()).unwrap();
        let graph = d.create("Test/Graph.lua").unwrap();
        d.call(&graph, "OnLeaveZone").unwrap();
    }

    /// An output a box's header declares but its graph never plugs does
    /// nothing when called; a dynamic one is left for the graph to fill in.
    #[test]
    fn unplugged_outputs_do_nothing() {
        let mut m = scripts().0;
        m.insert(
            "test/getstate.lua".into(),
            r#"
            -- DOMINO REFLECTION BOX START
            -- <ControlOut Name="Running" />
            -- <ControlOut Name="Acknowledged" />
            -- <ControlOut Name="Out" Dynamic="True"/>
            -- DOMINO REFLECTION BOX END
            G = {};
            function G:Get() self:Acknowledged(); self:Running() end
            export = G; G = nil;
            "#
            .into(),
        );
        let d = Domino::new(Scripts(m)).unwrap();
        let ran: bool = d
            .lua()
            .load(
                r#"
                local c = __domino_class("Test/GetState.lua")
                local ran = false
                c.Running = function() ran = true end
                c:Get()
                return ran and c.Out == nil
                "#,
            )
            .eval()
            .unwrap();
        assert!(ran);
        assert_eq!(control_outs("\n-- <ControlOut Name=\"A\"/>\n-- <ControlOut Name=\"B\" Delayed=\"true\">\nx = 1\n-- <ControlOut Name=\"C\"/>"), ["A", "B"]);
    }

    /// A box used statelessly by one graph and then by another that doesn't
    /// plug an output: the output does nothing, not the first graph's.
    #[test]
    fn stateless_outputs_are_unplugged_for_each_user() {
        let mut m = scripts().0;
        m.insert(
            "test/getstate.lua".into(),
            r#"
            -- <ControlOut Name="Running" />
            -- <ControlOut Name="Acknowledged" />
            G = {};
            function G:Get() self:Acknowledged(); self:Running() end
            export = G; G = nil;
            "#
            .into(),
        );
        // (The graphs as the generator writes them; the second, compiled
        // before the box had Acknowledged, plugs Running alone.)
        m.insert(
            "test/first.lua".into(),
            r#"
            export = {};
            function export:Go()
                local l0;
                l0 = Boxes[GetPathID("Test/GetState.lua")];
                l0._graph = self;
                l0.Running = function() calls = calls .. "r1" end;
                l0.Acknowledged = function() calls = calls .. "a1" end;
                l0:Get();
            end;
            "#
            .into(),
        );
        m.insert(
            "test/second.lua".into(),
            r#"
            export = {};
            function export:Go()
                local l0;
                l0 = Boxes[GetPathID("Test/GetState.lua")];
                l0._graph = self;
                l0.Running = function() calls = calls .. "r2" end;
                l0:Get();
            end;
            "#
            .into(),
        );
        let d = Domino::new(Scripts(m)).unwrap();
        let calls: String = d
            .lua()
            .load(
                r#"
                calls = ""
                __domino_class("Test/GetState.lua")
                __domino_class("Test/First.lua"):Go()
                __domino_class("Test/Second.lua"):Go()
                return calls
                "#,
            )
            .eval()
            .unwrap();
        assert_eq!(calls, "a1r1r2");
        // (Plugged in one place and called in another, it keeps its plugs.)
        let text = "function export:en_10()\n    local l0;\n    l0 = Boxes[GetPathID(\"Test/GetState.lua\")];\n    l0._graph = self;\n    l0.Running = self.f;\nend;\nfunction export:g()\n    l0 = Boxes[GetPathID(\"Test/GetState.lua\")];\n    l0:Get();\nend;\n";
        let out = plug_stateless(text, |_| vec!["Running".into(), "Acknowledged".into()]).unwrap();
        assert!(out.contains("    l0._graph = self;\n    l0.Acknowledged = DummyFunction;\n    l0.Running = self.f;"), "{out}");
        assert_eq!(out.matches("DummyFunction").count(), 1);
    }

    /// The id the game gives `Domino/System/Print_v2.lua`.
    #[test]
    fn path_ids_are_archive_hashes() {
        assert_eq!(path_id("Domino/System/Print_v2.lua"), "8578475447439923801");
        assert_eq!(path_id("Domino/System/Door.lua"), path_id(r"domino\system\door.lua"));
    }
}
